SELECT

FROM UserHoldAmountRewardConfig a WHERE 1 = 1

    AND a.currency = #{currency}


    AND a.holdAmount1 = #{holdAmount1}


    AND a.holdAmount2 = #{holdAmount2}


    AND a.holdLevel = #{holdLevel}


    AND a.holdRateDiscount = #{holdRateDiscount}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM UserHoldAmountRewardConfig a WHERE 1 = 1

    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.holdAmount1 = #{holdAmount1}


    AND a.holdAmount2 = #{holdAmount2}


    AND a.holdLevel LIKE CONCAT('%',#{holdLevel}, '%')


    AND a.holdRateDiscount = #{holdRateDiscount}


    AND a.state = #{state}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
